import { OUTFIT as C } from "./palette"

// Tab estilo outfit: una fila que ocupa todo el ancho, con divisores finos.
// La elegida se pinta de negro con texto blanco. (Tab estilo 1 = TileGroup.)
export function TabBar<T extends string>({
  options,
  value,
  onChange,
  className,
}: {
  options: { value: T; label: string }[]
  value: T
  onChange: (v: T) => void
  className?: string
}) {
  return (
    <div role="tablist" className={"flex flex-shrink-0 border-b " + (className ?? "")} style={{ borderColor: C.border }}>
      {options.map((o, i) => {
        const on = o.value === value
        return (
          <button
            key={o.value}
            type="button"
            role="tab"
            aria-selected={on}
            onClick={() => onChange(o.value)}
            className="flex flex-1 items-center justify-center px-2 py-4"
            style={{
              fontSize: 14,
              fontWeight: 400,
              background: on ? C.ink : C.white,
              color: on ? C.white : C.muted,
              borderRight: i < options.length - 1 ? "1px solid " + C.border : "none",
            }}
          >
            {o.label}
          </button>
        )
      })}
    </div>
  )
}

import { X } from "lucide-react"
import { OUTFIT as C } from "./palette"

// Filtro con chips en una fila que se desliza (ej: marcas). El elegido va en negro.
export function FilterChips<T extends string | null>({
  options,
  value,
  onChange,
  transparent = false,
}: {
  options: { value: T; label: string }[]
  value: T
  onChange: (v: T) => void
  /** fondo transparente para los no elegidos (en Mis prendas) en vez de blanco */
  transparent?: boolean
}) {
  return (
    <div className="flex gap-2 overflow-x-auto" style={{ scrollbarWidth: "none" }}>
      {options.map((o) => {
        const on = o.value === value
        return (
          <button
            key={String(o.value ?? "todo")}
            type="button"
            onClick={() => onChange(o.value)}
            className="flex-shrink-0 rounded-full px-3 py-1.5 text-xs font-medium"
            style={{
              background: on ? C.ink : transparent ? "transparent" : C.white,
              color: on ? C.white : C.text,
              border: "1px solid " + (on ? C.ink : C.border),
            }}
          >
            {o.label}
          </button>
        )
      })}
    </div>
  )
}

// Chip con borde negro y una cruz para borrarlo (marcas, modelos, tipos guardados)
export function ChipTag({
  label,
  selected,
  onSelect,
  onDelete,
}: {
  label: string
  selected?: boolean
  onSelect?: () => void
  onDelete?: () => void
}) {
  return (
    <div
      className="flex flex-shrink-0 items-center gap-1 rounded-full text-xs font-medium"
      style={{
        background: selected ? C.ink : C.white,
        color: selected ? C.white : C.ink,
        border: "1px solid " + C.ink,
        padding: "6px 8px 6px 10px",
      }}
    >
      <button type="button" onClick={onSelect}>{label}</button>
      {onDelete && (
        <button type="button" aria-label={"Borrar " + label} onClick={(e) => { e.stopPropagation(); onDelete() }} style={{ display: "flex", alignItems: "center", opacity: 0.5 }}>
          <X style={{ width: 10, height: 10 }} />
        </button>
      )}
    </div>
  )
}

import * as React from "react"
import { ChevronLeft, Plus } from "lucide-react"
import { OUTFIT as C } from "./palette"

const TONES = {
  primary: { background: C.ink, color: C.white },
  secondary: { background: C.light, color: C.ink },
  soft: { background: C.soft, color: C.ink },
  "danger-soft": { background: C.soft, color: C.danger },
  danger: { background: C.danger, color: C.white },
  "danger-text": { background: "transparent", color: C.danger },
  disabled: { background: C.light, color: C.muted },
} as const

// Botón grande estilo outfit: ancho completo (o flex-1 en filas), alto 48, bordes 12px.
export function ActionButton({
  tone = "primary",
  className,
  style,
  disabled,
  ...props
}: React.ComponentProps<"button"> & { tone?: keyof typeof TONES }) {
  return (
    <button
      type="button"
      disabled={disabled}
      className={"flex items-center justify-center gap-2 rounded-[12px] py-3 text-sm font-medium " + (className ?? "")}
      style={{ border: "none", ...(disabled ? TONES.disabled : TONES[tone]), ...style }}
      {...props}
    />
  )
}

// Botón punteado "Agregar nueva prenda"
export function DashedAddButton({ children = "Agregar nueva prenda", className, ...props }: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      className={"flex w-full items-center justify-center gap-2 rounded-[12px] py-3 text-sm " + (className ?? "")}
      style={{ border: "1.5px dashed " + C.border, color: C.muted, background: "transparent" }}
      {...props}
    >
      <Plus className="h-4 w-4" /> {children}
    </button>
  )
}

// Botón redondo gris para volver un paso
export function RoundBackButton({ disabled, ...props }: React.ComponentProps<"button">) {
  return (
    <button type="button" disabled={disabled} aria-label="Anterior" style={{ background: C.light, padding: 6, borderRadius: "50%", opacity: disabled ? 0.3 : 1 }} {...props}>
      <ChevronLeft className="h-4 w-4" style={{ color: C.ink }} />
    </button>
  )
}

import * as React from "react"
import { Archive, ImageIcon } from "lucide-react"
import { OUTFIT as C } from "./palette"

export type OutfitItem = {
  marca?: string
  modelo?: string
  tipo?: string
  imageUrl?: string
  imageZoom?: number
  imagePanX?: number
  imagePanY?: number
  archived?: boolean
  colors?: { name?: string; hex: string }[]
}

// Puntitos de color superpuestos (hasta 3 colores de una prenda)
export function ColorDots({ colors, size = 14 }: { colors?: { hex: string }[]; size?: number }) {
  if (!colors || colors.length === 0) return null
  const overlap = Math.round(size * 0.45)
  const totalWidth = size + (colors.length - 1) * (size - overlap)
  return (
    <span style={{ display: "inline-flex", position: "relative", width: totalWidth, height: size, flexShrink: 0 }}>
      {colors.map((c, i) => (
        <span
          key={i}
          style={{
            position: "absolute", left: i * (size - overlap), width: size, height: size, borderRadius: "50%",
            background: c.hex, boxShadow: c.hex === "#FFFFFF" ? `inset 0 0 0 1px ${C.border}` : undefined, zIndex: i,
          }}
        />
      ))}
    </span>
  )
}

function photoStyle(item: OutfitItem, framed = true): React.CSSProperties {
  return {
    position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", display: "block",
    ...(framed ? { transform: `scale(${item.imageZoom || 1}) translate(${item.imagePanX || 0}px, ${item.imagePanY || 0}px)`, transformOrigin: "center center" } : {}),
  }
}

function ArchivedBadge({ size = 18 }: { size?: number }) {
  return (
    <span style={{ position: "absolute", top: 4, right: 4, width: size, height: size, borderRadius: "50%", background: C.white, border: "1px solid " + C.light, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1 }}>
      <Archive style={{ width: size * 0.6, height: size * 0.6, color: C.muted }} />
    </span>
  )
}

const line = (color: string, size = 11): React.CSSProperties => ({ fontSize: size, fontWeight: 500, color, lineHeight: "14px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", maxWidth: "100%" })

// Ficha de prenda de las grillas de 3 columnas. `selected` = borde negro + puntito.
export function ItemCard({ item, selected, onClick, style }: { item: OutfitItem; selected?: boolean; onClick?: () => void; style?: React.CSSProperties }) {
  return (
    <div
      onClick={onClick}
      style={{ background: C.bg, border: "1.5px solid " + (selected ? C.ink : "transparent"), borderRadius: 12, padding: 8, textAlign: "center", minWidth: 0, cursor: onClick ? "pointer" : undefined, ...style }}
    >
      <div style={{ width: "100%", aspectRatio: "1/1", borderRadius: 8, background: C.soft, marginBottom: 16, position: "relative", overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center" }}>
        {item.imageUrl ? <img src={item.imageUrl} alt="" style={photoStyle(item)} /> : <ImageIcon style={{ width: 24, height: 24, color: C.muted }} />}
        {item.archived && <ArchivedBadge />}
        {selected && <span style={{ position: "absolute", top: 4, right: 4, width: 6, height: 6, borderRadius: "50%", background: C.ink, zIndex: 1 }} />}
      </div>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
        <div style={{ display: "flex", justifyContent: "center" }}><ColorDots colors={item.colors} size={11} /></div>
        {item.marca && <p style={line(C.ink)}>{item.marca}</p>}
        {item.modelo && <p style={line(C.subtle)}>{item.modelo}</p>}
        {item.tipo && <p style={line(C.muted)}>{item.tipo}</p>}
      </div>
    </div>
  )
}

// Prenda chiquita de la tabla del historial (foto 60px)
export function ItemCardSmall({ item }: { item: OutfitItem }) {
  return (
    <div className="flex flex-col items-center">
      <div style={{ width: 60, height: 60, borderRadius: 6, background: C.soft, overflow: "hidden", position: "relative", flexShrink: 0, marginBottom: 6, display: "flex", alignItems: "center", justifyContent: "center" }}>
        {item.imageUrl ? <img src={item.imageUrl} alt="" style={photoStyle(item)} /> : <ImageIcon style={{ width: 20, height: 20, color: C.muted }} />}
        {item.archived && <ArchivedBadge size={16} />}
      </div>
      <div className="flex flex-col items-center" style={{ gap: 3 }}>
        <div className="flex justify-center" style={{ height: 10 }}><ColorDots colors={item.colors} size={10} /></div>
        {item.marca && <span style={{ color: C.ink, fontSize: 10, lineHeight: "14px", fontWeight: 500 }}>{item.marca}</span>}
        {item.modelo && <span style={{ color: C.subtle, fontSize: 10, fontWeight: 500, lineHeight: "14px" }}>{item.modelo}</span>}
        {item.tipo && <span style={{ color: C.muted, fontSize: 10, fontWeight: 500, lineHeight: "14px" }}>{item.tipo}</span>}
      </div>
    </div>
  )
}

// Fila de lista con foto 64px a la izquierda y algo a la derecha (estadísticas, archivadas)
export function ItemRow({ item, right, gray }: { item: OutfitItem; right?: React.ReactNode; gray?: boolean }) {
  return (
    <div className="flex rounded-[12px]" style={{ background: C.bg, gap: 8, padding: 8, alignItems: "stretch" }}>
      <div style={{ width: 64, height: 64, borderRadius: 8, background: C.soft, flexShrink: 0, overflow: "hidden", position: "relative" }}>
        {item.imageUrl && <img src={item.imageUrl} alt="" style={{ ...photoStyle(item, false), filter: gray ? "grayscale(100%)" : undefined }} />}
      </div>
      <div className="min-w-0 flex-1" style={{ display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
        <div><ColorDots colors={item.colors} size={11} /></div>
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          {item.marca && <p style={{ ...line(item.archived ? C.muted : C.ink, 12), lineHeight: "15px" }}>{item.marca}</p>}
          <p style={{ ...line(C.muted, 12), lineHeight: "15px" }}>
            {item.modelo && <span style={{ color: C.subtle }}>{item.modelo}</span>}
            {item.modelo && item.tipo && <span> · </span>}
            {item.tipo && <span>{item.tipo}</span>}
          </p>
        </div>
      </div>
      {right && <div style={{ flexShrink: 0, display: "flex", flexDirection: "column", alignItems: "flex-end", justifyContent: "space-between" }}>{right}</div>}
    </div>
  )
}

import { Check } from "lucide-react"
import { OUTFIT as C } from "./palette"

type Swatch = { name: string; hex: string }
const LIGHTS = ["#FFFFFF", "#D4D4D4", "#F0E6D6"]

// Selector de colores en círculos de 30px (hasta `max` elegidos). El elegido lleva un aro negro.
export function ColorSwatches({ colors, value, onToggle, max = 3 }: { colors: Swatch[]; value: Swatch[]; onToggle: (c: Swatch) => void; max?: number }) {
  return (
    <div className="flex gap-2 overflow-x-auto" style={{ scrollbarWidth: "none", padding: "4px 2px 6px" }}>
      {colors.map((c) => {
        const sel = value.find((p) => p.hex === c.hex)
        const light = LIGHTS.includes(c.hex)
        return (
          <button
            key={c.hex}
            type="button"
            onClick={() => onToggle(c)}
            title={c.name}
            className="relative flex-shrink-0"
            style={{
              width: 30, height: 30, borderRadius: "50%", background: c.hex,
              border: light ? "1.5px solid " + C.border : "2px solid transparent",
              boxShadow: sel ? "0 0 0 2px " + C.white + ", 0 0 0 4px " + C.ink : undefined,
              outline: "none", transition: "box-shadow 0.15s",
              opacity: !sel && value.length >= max ? 0.35 : 1,
            }}
          >
            {sel && (
              <span style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <Check style={{ width: 12, height: 12, color: light ? C.ink : C.white }} />
              </span>
            )}
          </button>
        )
      })}
    </div>
  )
}

import { OUTFIT as C } from "./palette"

export type DayOption = { dateStr: string; dayName: string; label: string; isToday?: boolean; marked?: boolean }

// Fila de días que se desliza. Elegido = negro; hoy = borde negro; con outfit = puntito.
export function DateStrip({ days, value, onChange }: { days: DayOption[]; value: string; onChange: (d: string) => void }) {
  return (
    <div className="flex gap-2 overflow-x-auto" style={{ scrollbarWidth: "none", padding: "4px 0" }}>
      {days.map((d) => {
        const sel = value === d.dateStr
        return (
          <button
            key={d.dateStr}
            type="button"
            data-today={d.isToday}
            onClick={() => onChange(d.dateStr)}
            className="flex flex-shrink-0 flex-col items-center px-3 py-2 transition-all"
            style={{ background: sel ? C.ink : d.isToday ? C.soft : C.white, border: "1px solid " + (sel ? C.ink : d.isToday ? C.ink : C.border), minWidth: 54, position: "relative", borderRadius: 8 }}
          >
            {d.marked && <span style={{ position: "absolute", top: 4, right: 4, width: 6, height: 6, borderRadius: "50%", background: sel ? C.white : C.ink }} />}
            <span className="text-xs font-medium" style={{ color: sel ? C.white : C.ink }}>{d.dayName.slice(0, 3)}</span>
            <span className="mt-0.5 text-xs" style={{ color: sel ? "rgba(255,255,255,0.7)" : C.muted }}>{d.label}</span>
          </button>
        )
      })}
    </div>
  )
}

import * as React from "react"
import { X } from "lucide-react"
import { OUTFIT as C } from "./palette"
import { ActionButton } from "./action-button"

// Hoja que sube desde abajo: título + cruz con línea abajo, y el contenido.
// `inline` la muestra dentro de la página (para la guía) en vez de flotando arriba de todo.
export function BottomSheet({ open, onClose, title, children, inline }: { open: boolean; onClose: () => void; title: React.ReactNode; children: React.ReactNode; inline?: boolean }) {
  if (!open) return null
  return (
    <div className={(inline ? "relative h-full " : "fixed inset-0 ") + "flex items-end justify-center"} style={{ background: "rgba(0,0,0,0.4)", zIndex: 200 }} onClick={onClose}>
      <div className="w-full rounded-t-[16px]" style={{ background: C.white }} onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-4 py-4" style={{ borderBottom: "1px solid " + C.border }}>
          <span className="text-sm font-medium" style={{ color: C.ink }}>{title}</span>
          <button type="button" aria-label="Cerrar" onClick={onClose} style={{ background: "transparent", border: "none", padding: 0 }}>
            <X style={{ width: 20, height: 20, color: C.muted }} />
          </button>
        </div>
        {children}
      </div>
    </div>
  )
}

// Confirmación en hoja de abajo: pregunta, aclaración en gris, Volver + acción en rojo
export function ConfirmSheet({ open, onClose, title, question, detail, confirmLabel, onConfirm, inline }: {
  open: boolean; onClose: () => void; title: string; question: string; detail: string; confirmLabel: string; onConfirm: () => void; inline?: boolean
}) {
  return (
    <BottomSheet open={open} onClose={onClose} title={title} inline={inline}>
      <div className="p-6 pb-10">
        <p className="mb-1 text-sm" style={{ color: C.ink }}>{question}</p>
        <p className="mb-6 text-sm" style={{ color: C.muted }}>{detail}</p>
        <div className="flex gap-3">
          <ActionButton tone="secondary" className="flex-1" onClick={onClose}>Volver</ActionButton>
          <ActionButton tone="danger" className="flex-1" onClick={onConfirm}>{confirmLabel}</ActionButton>
        </div>
      </div>
    </BottomSheet>
  )
}

// Ventana centrada (ej: Nueva prenda): título + subtítulo, cruz, línea abajo
export function CenterModal({ open, onClose, title, subtitle, children, footer, inline }: {
  open: boolean; onClose: () => void; title: string; subtitle?: string; children: React.ReactNode; footer?: React.ReactNode; inline?: boolean
}) {
  if (!open) return null
  return (
    <div className={(inline ? "relative h-full " : "fixed inset-0 ") + "flex items-center justify-center p-4"} style={{ background: "rgba(0,0,0,0.5)", zIndex: 200 }}>
      <div className="relative w-full max-w-sm rounded-[12px]" style={{ background: C.white, maxHeight: "92vh", overflowY: "auto" }}>
        <div className="flex items-center justify-between border-b px-6 pt-6 pb-4" style={{ borderColor: C.border }}>
          <div>
            <h3 className="text-sm font-medium" style={{ color: C.ink }}>{title}</h3>
            {subtitle && <p className="mt-0.5 text-xs" style={{ color: C.muted }}>{subtitle}</p>}
          </div>
          <button type="button" aria-label="Cerrar" onClick={onClose}><X className="h-5 w-5" style={{ color: C.muted }} /></button>
        </div>
        <div className="space-y-5 px-6 py-5">{children}</div>
        {footer && <div className="px-6 pb-6">{footer}</div>}
      </div>
    </div>
  )
}

import type { LucideIcon } from "lucide-react"
import { OUTFIT as C } from "./palette"

// Barra de abajo: íconos de 24px, el activo en negro con un puntito de 4px debajo.
export function BottomNav<T extends string>({ items, value, onChange, fixed = true }: {
  items: { key: T; icon: LucideIcon; label?: string }[]; value: T; onChange: (k: T) => void; fixed?: boolean
}) {
  return (
    <nav style={{ position: fixed ? "fixed" : "relative", bottom: 0, left: 0, right: 0, height: 84, background: "transparent", display: "flex", alignItems: "center", zIndex: 50 }}>
      {items.map(({ key, icon: Icon, label }) => {
        const on = value === key
        return (
          <button key={key} type="button" aria-label={label} onClick={() => onChange(key)} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100%", background: "transparent", border: "none", gap: 6 }}>
            <Icon style={{ width: 24, height: 24, color: on ? C.ink : C.muted }} />
            <span style={{ width: 4, height: 4, borderRadius: "50%", background: on ? C.ink : "transparent" }} />
          </button>
        )
      })}
    </nav>
  )
}

import * as React from "react"
import { Plus } from "lucide-react"
import { OUTFIT as C } from "./palette"

// Caja blanca de sección (bordes 12px, sombra suave)
export function Panel({ className, style, ...props }: React.ComponentProps<"div">) {
  return <div className={"rounded-[12px] shadow-sm " + (className ?? "")} style={{ background: C.white, ...style }} {...props} />
}

// Etiqueta gris chiquita arriba de un campo
export function FieldLabel({ children, right }: { children: React.ReactNode; right?: React.ReactNode }) {
  return (
    <div className="mb-2 flex items-center">
      <p className="text-xs" style={{ color: C.muted }}>{children}</p>
      {right && <span className="ml-auto text-xs">{right}</span>}
    </div>
  )
}

// Campo de texto + botón cuadrado "+" (negro si hay texto)
export function InputAdd({ value, onChange, onAdd, placeholder }: { value: string; onChange: (v: string) => void; onAdd: () => void; placeholder?: string }) {
  const has = value.trim() !== ""
  return (
    <div className="flex gap-2">
      <input
        type="text" placeholder={placeholder} value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") onAdd() }}
        className="flex-1 rounded-[8px] px-3 py-2 text-sm outline-none"
        style={{ background: C.bg, border: "1px solid " + C.border, color: C.text }}
      />
      <button type="button" onClick={onAdd} disabled={!has} className="rounded-[8px] px-3 py-2" style={{ background: has ? C.ink : C.light, color: has ? C.white : C.muted }}>
        <Plus className="h-4 w-4" />
      </button>
    </div>
  )
}

// Estado vacío: círculo gris con ícono, título y texto
export function EmptyState({ icon, title, text }: { icon: React.ReactNode; title: string; text: string }) {
  return (
    <div className="flex flex-col items-center justify-center gap-4 text-center">
      <div className="flex h-16 w-16 items-center justify-center rounded-full" style={{ background: C.soft }}>{icon}</div>
      <div>
        <p className="mb-1 text-base font-medium" style={{ color: C.text }}>{title}</p>
        <p className="text-sm" style={{ color: C.muted }}>{text}</p>
      </div>
    </div>
  )
}

// Aviso flotante en forma de píldora abajo al centro
export function Toast({ message, fixed = true }: { message: string; fixed?: boolean }) {
  return (
    <div
      className={(fixed ? "fixed bottom-6 left-1/2 " : "inline-block ") + "rounded-full px-5 py-3 text-sm font-medium"}
      style={{ background: C.soft, color: C.ink, transform: fixed ? "translateX(-50%) translateY(" + (message ? "0px" : "24px") + ")" : undefined, opacity: message ? 1 : 0, transition: "all 0.3s ease", pointerEvents: "none", zIndex: 60 }}
    >
      {message}
    </div>
  )
}
